<template>
  <aside class="workflow-inspector" aria-label="工作流属性面板">
    <nav class="workflow-inspector__tabs" aria-label="属性面板标签">
      <button v-for="tab in tabs" :key="tab.value" type="button" :class="{ active: activeTab === tab.value }" @click="activeTab = tab.value"><i :class="tab.icon"></i><span>{{ tab.label }}</span></button>
    </nav>

    <section v-if="activeTab === 'node'" class="workflow-inspector__body">
      <template v-if="selectedNode">
        <header class="workflow-inspector__heading"><span class="workflow-inspector__node-icon" :style="{ '--node-color': selectedNode.data.color }"><i :class="`fa ${selectedNode.data.icon}`"></i></span><div><h2>{{ selectedNode.data.label }}</h2><p>{{ nodeTypeLabel(selectedNode.type) }}</p></div></header>
        <label class="workflow-field">节点名称<input v-model.trim="draft.label" type="text" maxlength="80" @change="apply" /></label>
        <label v-if="isTask" class="workflow-field">步骤 ID<input v-model.trim="draft.stepId" type="text" pattern="[A-Za-z_][A-Za-z0-9_]*" @change="apply" /></label>
        <label v-if="isTask" class="workflow-field">输出变量<input v-model.trim="draft.output" type="text" placeholder="例如 file_list" @change="apply" /></label>

        <template v-if="isTask">
          <label class="workflow-field">能力来源<select v-model="action.provider" @change="onProviderChanged"><option value="builtin">内置函数</option><option value="plugin">云插件函数</option><option value="api">平台 API</option></select></label>
          <label v-if="action.provider !== 'plugin'" class="workflow-field">能力<select v-model="capabilityKey" @change="applyCapability"><option value="">手动配置</option><option v-for="capability in matchingCapabilities" :key="capability.capabilityKey" :value="capability.capabilityKey">{{ capability.displayName }}</option></select></label>
          <div v-if="action.provider === 'plugin'" class="workflow-field-grid"><label class="workflow-field">插件 ID<input v-model.trim="action.pluginId" @change="apply" /></label><label class="workflow-field">函数<input v-model.trim="action.function" @change="apply" /></label></div>
          <div v-else class="workflow-field-grid"><label class="workflow-field">服务<input v-model.trim="action.service" @change="apply" /></label><label class="workflow-field">方法<input v-model.trim="action.method" @change="apply" /></label></div>
          <label class="workflow-field">参数 JSON <button class="workflow-field__fx" type="button" title="选择变量引用" @click="referencePickerOpen = !referencePickerOpen">fx</button><textarea v-model="argumentText" spellcheck="false" @change="applyArguments"></textarea><span v-if="referencePickerOpen" class="workflow-reference-picker"><button v-for="reference in availableReferences" :key="reference" type="button" @click="insertReference(reference)">{{ reference }}</button></span></label>
          <p v-if="argumentError" class="workflow-inline-error"><i class="fa fa-exclamation-circle"></i>{{ argumentError }}</p>
          <details v-if="selectedCapability" class="workflow-schema"><summary>能力输入约束</summary><pre>{{ formatSchema(selectedCapability.inputSchemaJson) }}</pre></details>
        </template>

        <label v-if="needsExpression" class="workflow-field">表达式 <button class="workflow-field__fx" type="button" title="选择变量引用" @click="referencePickerOpen = !referencePickerOpen">fx</button><textarea v-model.trim="draft.expression" class="workflow-expression" spellcheck="false" placeholder="vars.count > 0 && size(vars.files) > 0" @change="apply"></textarea><span v-if="referencePickerOpen" class="workflow-reference-picker"><button v-for="reference in availableReferences" :key="reference" type="button" @click="insertReference(reference)">{{ reference }}</button></span></label>
        <div v-if="selectedNode.type === 'foreach'" class="workflow-field-grid"><label class="workflow-field">迭代变量<input v-model.trim="draft.iterator" @change="apply" /></label><label class="workflow-field">集合引用<input v-model.trim="draft.collection" placeholder="vars.files" @change="apply" /></label></div>
        <label v-if="selectedNode.type === 'wait'" class="workflow-field">等待类型<select v-model="draft.waitType" @change="apply"><option value="approval">人工审批</option></select></label>
        <label v-if="selectedNode.type === 'try'" class="workflow-field">Catch 变量<input v-model.trim="draft.catchBinding" placeholder="error" @change="apply" /></label>
        <label v-if="selectedNode.type === 'note'" class="workflow-field">便签内容<textarea v-model="draft.note" @change="apply"></textarea></label>
        <label class="workflow-field">超时<select v-model="draft.timeout" @change="apply"><option value="">使用运行时默认值</option><option value="30s">30 秒</option><option value="5m">5 分钟</option><option value="30m">30 分钟</option><option value="24h">24 小时</option></select></label>
        <fieldset v-if="isTask" class="workflow-retry"><legend>重试策略</legend><label><input v-model="retryEnabled" type="checkbox" @change="apply" />启用重试</label><div v-if="retryEnabled" class="workflow-field-grid"><label class="workflow-field">最大次数<input v-model.number="retry.maxAttempts" type="number" min="1" max="20" @change="apply" /></label><label class="workflow-field">退避<select v-model="retry.strategy" @change="apply"><option value="fixed">固定</option><option value="linear">线性</option><option value="exponential">指数</option></select></label></div></fieldset>
        <fieldset class="workflow-advanced"><legend>画布行为</legend><label><input v-model="draft.disabled" type="checkbox" @change="apply" />禁用节点（不会生成 DSL）</label><label><input v-model="draft.locked" type="checkbox" @change="apply" />锁定位置</label><label><input v-model="draft.collapsed" type="checkbox" @change="apply" />折叠详情</label><div class="workflow-field-grid"><label class="workflow-field">节点颜色<input v-model="draft.color" type="color" title="节点颜色" @change="apply" /></label><label class="workflow-field">图标类<input v-model.trim="draft.icon" placeholder="fa-cube" @change="apply" /></label></div></fieldset>
        <footer class="workflow-inspector__actions"><button type="button" class="workflow-button workflow-button--subtle" @click="resetDraft">重置</button><button type="button" class="workflow-button workflow-button--primary" @click="apply"><i class="fa fa-check"></i>应用</button></footer>
      </template>
      <template v-else-if="selectedEdge">
        <header class="workflow-inspector__heading"><span class="workflow-inspector__node-icon workflow-inspector__node-icon--edge"><i class="fa fa-long-arrow-right"></i></span><div><h2>{{ edgeKindLabel(selectedEdge.data.kind) }}</h2><p>连线外观独立于 CloudFlow 控制流语义</p></div></header>
        <label class="workflow-field">连线标签<input v-model.trim="edgeDraft.label" maxlength="80" placeholder="例如：通过审批" @change="applyEdge" /></label>
        <label class="workflow-field">说明<textarea v-model.trim="edgeDraft.description" placeholder="供协作成员阅读，不写入 DSL" @change="applyEdge"></textarea></label>
        <label v-if="['condition-true', 'condition-false'].includes(selectedEdge.data.kind)" class="workflow-field">条件表达式<textarea v-model.trim="edgeDraft.condition" class="workflow-expression" placeholder="vars.count > 0" @change="applyEdge"></textarea></label>
        <div class="workflow-field-grid"><label class="workflow-field">路由<select v-model="edgeDraft.route" @change="applyEdge"><option value="smoothstep">直角平滑</option><option value="bezier">贝塞尔曲线</option><option value="straight">直线</option></select></label><label class="workflow-field">线型<select v-model="edgeDraft.lineStyle" @change="applyEdge"><option value="auto">语义默认</option><option value="solid">实线</option><option value="dashed">虚线</option><option value="dotted">点线</option></select></label></div>
        <label class="workflow-field">连线颜色<input v-model="edgeDraft.color" type="color" title="连线颜色" @change="applyEdge" /></label>
        <label class="workflow-field">变量映射 JSON<textarea v-model="edgeMappingText" class="workflow-expression" placeholder='{"source":"target"}' @change="applyEdgeMapping"></textarea></label>
        <fieldset class="workflow-advanced"><legend>连线行为</legend><label><input v-model="edgeDraft.locked" type="checkbox" @change="applyEdge" />锁定连线，避免误操作</label></fieldset>
        <footer class="workflow-inspector__actions"><button type="button" class="workflow-button workflow-button--subtle" @click="resetEdgeDraft">重置</button><button type="button" class="workflow-button workflow-button--primary" @click="applyEdge"><i class="fa fa-check"></i>应用</button></footer>
      </template>
      <div v-else class="workflow-inspector__empty"><i class="fa fa-sliders"></i><strong>选择一个节点</strong><p>右键或单击画布中的节点，配置其与 CloudFlow DSL 一一对应的字段。</p></div>
    </section>

    <section v-else-if="activeTab === 'variables'" class="workflow-inspector__body">
      <header class="workflow-inspector__section-title"><div><h2>全局变量</h2><p>类型、来源和引用均遵循 CloudFlow V1.1。</p></div><button class="workflow-button workflow-button--primary" type="button" @click="addVariable"><i class="fa fa-plus"></i>变量</button></header>
      <div v-if="!project.variables.length" class="workflow-inspector__empty workflow-inspector__empty--compact"><i class="fa fa-code"></i><p>还没有全局变量。输入变量只允许由启动 API 覆盖。</p></div>
      <article v-for="(variable, index) in project.variables" :key="`${variable.name}-${index}`" class="workflow-variable-row"><div class="workflow-variable-row__main"><input :value="variable.name" aria-label="变量名" @change="updateVariable(index, { name: ($event.target as HTMLInputElement).value })" /><select :value="variable.type" aria-label="变量类型" @change="updateVariable(index, { type: ($event.target as HTMLSelectElement).value as any })"><option v-for="type in variableTypes" :key="type" :value="type">{{ type }}</option></select><select :value="variable.source" aria-label="变量来源" @change="updateVariable(index, { source: ($event.target as HTMLSelectElement).value as any })"><option value="input">输入</option><option value="local">本地</option><option value="deferred">延迟</option></select></div><div class="workflow-variable-row__value"><input :value="stringifyVariableValue(variable.value)" :disabled="variable.source === 'deferred'" placeholder="默认值 / JSON / vars.xxx" @change="updateVariableValue(index, ($event.target as HTMLInputElement).value)" /><button type="button" title="删除变量" aria-label="删除变量" @click="removeVariable(index)"><i class="fa fa-trash-o"></i></button></div><label v-if="variable.source === 'input'" class="workflow-variable-row__required"><input :checked="!!variable.required" type="checkbox" @change="updateVariable(index, { required: ($event.target as HTMLInputElement).checked })" />启动时必填</label></article>
    </section>

    <section v-else-if="activeTab === 'workflow'" class="workflow-inspector__body">
      <header class="workflow-inspector__section-title"><div><h2>工作流设置</h2><p>这些设置直接映射 metadata、trigger 和 runtime 块。</p></div></header>
      <label class="workflow-field">工作流标识<input :value="project.metadata.name" @change="updateMetadata('name', ($event.target as HTMLInputElement).value)" /></label>
      <label class="workflow-field">显示名称<input :value="project.metadata.displayName" @change="updateMetadata('displayName', ($event.target as HTMLInputElement).value)" /></label>
      <label class="workflow-field">描述<textarea :value="project.metadata.description" @change="updateMetadata('description', ($event.target as HTMLTextAreaElement).value)"></textarea></label>
      <label class="workflow-field">触发方式<select :value="project.trigger.type" @change="updateTriggerType(($event.target as HTMLSelectElement).value as any)"><option value="manual">手动</option><option value="schedule">定时</option><option value="event">事件</option><option value="http">HTTP</option></select></label>
      <template v-if="project.trigger.type === 'schedule'"><label class="workflow-field">Cron<input :value="project.trigger.cron" placeholder="0 8 * * 1" @change="updateTrigger('cron', ($event.target as HTMLInputElement).value)" /></label><label class="workflow-field">时区<input :value="project.trigger.timezone" placeholder="Asia/Shanghai" @change="updateTrigger('timezone', ($event.target as HTMLInputElement).value)" /></label></template>
      <label v-if="project.trigger.type === 'event'" class="workflow-field">事件名称<input :value="project.trigger.event" placeholder="FileUploaded" @change="updateTrigger('event', ($event.target as HTMLInputElement).value)" /></label>
      <label v-if="project.trigger.type === 'http'" class="workflow-field">路径<input :value="project.trigger.path" placeholder="/webhook/start" @change="updateTrigger('path', ($event.target as HTMLInputElement).value)" /></label>
      <fieldset class="workflow-runtime"><legend>运行时</legend><label class="workflow-field">全局超时<select :value="project.runtime.timeout" @change="updateRuntime('timeout', ($event.target as HTMLSelectElement).value)"><option value="">未设置</option><option value="30s">30 秒</option><option value="5m">5 分钟</option><option value="30m">30 分钟</option><option value="24h">24 小时</option></select></label><label class="workflow-field">最大并行数<input :value="project.runtime.maxParallel" type="number" min="1" max="100" @change="updateRuntime('maxParallel', Number(($event.target as HTMLInputElement).value) || undefined)" /></label></fieldset>
    </section>

    <section v-else class="workflow-inspector__body workflow-help">
      <h2>CloudFlow 画布帮助</h2><p>画布只保存 Runtime 能够编译的结构。`if/else`、`foreach`、`while`、`parallel`、`try/catch/finally`、`wait` 与 `assert` 均可直接生成 DSL。</p><dl><dt>条件端口</dt><dd>绿色端口生成 true 分支，红色端口生成 false 分支。</dd><dt>控制容器</dt><dd>把节点连接到循环、并行或异常处理端口，即进入对应的嵌套块。</dd><dt>变量引用</dt><dd>使用 <code>vars.name</code> 或 <code>steps.step_id.output</code>。</dd><dt>语言边界</dt><dd>当前 Runtime 不支持 match/case、多 catch 或独立 Output 节点；IDE 不会生成这些无效结构。</dd></dl><a href="/docs/plugins/workflows" target="_blank" rel="noopener noreferrer">打开工作流开发文档 <i class="fa fa-external-link"></i></a>
    </section>
  </aside>
</template>

<script setup lang="ts">
// [AUDIT FIX 5.1] 属性面板使用受控草稿，复杂 JSON 只有在合法时才写入画布状态。
import { computed, ref, watch } from 'vue'
import type { CapabilityInfo } from '@/api/modules/workflows'
import type { CloudFlowVariable, WorkflowVisualAction, WorkflowVisualEdge, WorkflowVisualEdgeData, WorkflowVisualNode, WorkflowVisualNodeData, WorkflowVisualProject } from '@/types/cloudflowVisual'

const props = withDefaults(defineProps<{ project: WorkflowVisualProject; selectedNode: WorkflowVisualNode | null; selectedEdge?: WorkflowVisualEdge | null; capabilities?: CapabilityInfo[] }>(), { selectedEdge: null, capabilities: () => [] })
const emit = defineEmits<{ 'update-node': [id: string, patch: Partial<WorkflowVisualNodeData>]; 'update-edge': [id: string, patch: Partial<WorkflowVisualEdgeData>]; 'update-project': [mutator: (draft: WorkflowVisualProject) => void]; 'insert-reference': [] }>()
const activeTab = ref<'node' | 'variables' | 'workflow' | 'help'>('node')
const draft = ref<WorkflowVisualNodeData>({ label: '', order: 0 })
const action = ref<WorkflowVisualAction>({ provider: 'builtin', service: 'file', method: 'list', arguments: {} })
const argumentText = ref('{}'); const argumentError = ref(''); const capabilityKey = ref('')
const retryEnabled = ref(false); const retry = ref({ maxAttempts: 3, strategy: 'exponential' as const })
const edgeDraft = ref<WorkflowVisualEdgeData>({ kind: 'dependency', route: 'smoothstep', lineStyle: 'auto', color: '#64748b' })
const edgeMappingText = ref('{}')
const referencePickerOpen = ref(false)
const tabs = [{ value: 'node' as const, label: '属性', icon: 'fa fa-sliders' }, { value: 'variables' as const, label: '变量', icon: 'fa fa-code' }, { value: 'workflow' as const, label: '设置', icon: 'fa fa-cog' }, { value: 'help' as const, label: '帮助', icon: 'fa fa-question-circle-o' }]
const variableTypes = ['string', 'number', 'boolean', 'array', 'object', 'file', 'user', 'space']
const selectedNode = computed(() => props.selectedNode)
const selectedEdge = computed(() => props.selectedEdge || null)
const isTask = computed(() => ['task', 'plugin', 'api'].includes(selectedNode.value?.type || ''))
const needsExpression = computed(() => ['condition', 'while', 'assert'].includes(selectedNode.value?.type || ''))
const matchingCapabilities = computed(() => props.capabilities.filter((capability) => action.value.provider === 'plugin' ? capability.sourceType === 'PLUGIN' : action.value.provider === 'api' ? ['API', 'PLATFORM_API'].includes(capability.sourceType) : capability.sourceType === 'BUILTIN'))
const selectedCapability = computed(() => props.capabilities.find((capability) => capability.capabilityKey === capabilityKey.value))
const availableReferences = computed(() => {
  const globals = props.project.variables.map((item) => `vars.${item.name}`)
  const outputs = props.project.nodes.filter((node) => node.data.stepId && node.data.output).map((node) => `steps.${node.data.stepId}.output${node.data.output ? `.${node.data.output}` : ''}`)
  return [...globals, ...outputs].slice(0, 40)
})
watch(selectedNode, () => resetDraft(), { immediate: true, deep: true })
watch(selectedEdge, () => resetEdgeDraft(), { immediate: true, deep: true })
function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)) as T }
function resetDraft() { const node = selectedNode.value; draft.value = clone(node?.data || { label: '', order: 0 }); action.value = clone(node?.data.action || { provider: 'builtin', service: 'file', method: 'list', arguments: {} }); argumentText.value = JSON.stringify(action.value.arguments || {}, null, 2); argumentError.value = ''; retryEnabled.value = !!node?.data.retry; retry.value = clone(node?.data.retry || { maxAttempts: 3, strategy: 'exponential' }); referencePickerOpen.value = false }
function apply() { if (!selectedNode.value) return; const patch: Partial<WorkflowVisualNodeData> = { ...draft.value, action: clone(action.value), retry: retryEnabled.value ? clone(retry.value) : undefined }; emit('update-node', selectedNode.value.id, patch) }
function applyArguments() { try { action.value.arguments = JSON.parse(argumentText.value || '{}'); argumentError.value = ''; apply() } catch { argumentError.value = '参数必须是合法 JSON；变量引用请使用字符串，例如 "vars.files"。' } }
function onProviderChanged() { if (action.value.provider === 'plugin') { action.value = { provider: 'plugin', pluginId: '', function: 'run', version: '1', arguments: action.value.arguments || {} } } else action.value = { provider: action.value.provider, service: 'file', method: 'list', arguments: action.value.arguments || {} }; capabilityKey.value = ''; apply() }
function applyCapability() { const capability = selectedCapability.value; if (!capability) return; const [provider, ...rest] = capability.capabilityKey.split(':'); const identifier = rest.join(':'); if (provider === 'plugin') { const [pluginId, func] = identifier.split(':'); action.value = { provider: 'plugin', pluginId, function: func || 'run', version: capability.sourceVersion || '1', arguments: {} } } else { const [service, method] = identifier.split('.'); action.value = { provider: provider === 'api' ? 'api' : 'builtin', service, method, arguments: {} } } argumentText.value = JSON.stringify(action.value.arguments, null, 2); apply() }
function insertVariableReference() { insertReference(availableReferences.value[0] || 'vars.variable_name') }
function insertReference(candidate: string) { if (needsExpression.value) draft.value.expression = `${draft.value.expression || ''}${draft.value.expression ? ' ' : ''}${candidate}`; else argumentText.value = argumentText.value.replace(/\{\s*\}/, `{\n  "value": "${candidate}"\n}`); referencePickerOpen.value = false; emit('insert-reference') }
function resetEdgeDraft() { const edge = selectedEdge.value; edgeDraft.value = clone(edge?.data || { kind: 'dependency', route: 'smoothstep', lineStyle: 'auto', color: '#64748b' }); edgeMappingText.value = JSON.stringify(edge?.data.variableMapping || {}, null, 2) }
function applyEdge() { if (!selectedEdge.value) return; emit('update-edge', selectedEdge.value.id, clone(edgeDraft.value)) }
function applyEdgeMapping() { try { edgeDraft.value.variableMapping = JSON.parse(edgeMappingText.value || '{}'); applyEdge() } catch { argumentError.value = '变量映射必须是合法 JSON。' } }
function formatSchema(value: string) { try { return JSON.stringify(JSON.parse(value || '{}'), null, 2) } catch { return value || '未声明 Schema' } }
function nodeTypeLabel(type: string) { return ({ trigger: '入口配置', task: '执行任务', plugin: '插件能力', api: '平台能力', condition: '条件分支', foreach: '集合循环', while: '条件循环', parallel: '并行分支', try: '异常处理', wait: '人工等待', assert: '运行时断言', group: '画布分组', note: '非执行注释' } as Record<string, string>)[type] || type }
function edgeKindLabel(kind: string) { return ({ dependency: '执行依赖', 'condition-true': '条件为真', 'condition-false': '条件为假', 'loop-body': '循环体', 'parallel-branch': '并行分支', 'try-branch': 'Try 分支', 'catch-branch': 'Catch 分支', 'finally-branch': 'Finally 分支' } as Record<string, string>)[kind] || kind }
function addVariable() { emit('update-project', (draftProject) => draftProject.variables.push({ name: `variable_${draftProject.variables.length + 1}`, type: 'string', source: 'input', required: false })) }
function updateVariable(index: number, patch: Partial<CloudFlowVariable>) { emit('update-project', (draftProject) => { const item = draftProject.variables[index]; if (item) Object.assign(item, patch) }) }
function updateVariableValue(index: number, value: string) { let parsed: unknown = value; try { parsed = JSON.parse(value) } catch { /* string 或引用保留文本 */ } updateVariable(index, { value: parsed }) }
function stringifyVariableValue(value: unknown) { return value === undefined ? '' : typeof value === 'string' ? value : JSON.stringify(value) }
function removeVariable(index: number) { emit('update-project', (draftProject) => draftProject.variables.splice(index, 1)) }
function updateMetadata(key: string, value: string) { emit('update-project', (draftProject) => { (draftProject.metadata as any)[key] = value }) }
function updateTriggerType(type: WorkflowVisualProject['trigger']['type']) { emit('update-project', (draftProject) => { draftProject.trigger = type === 'schedule' ? { type, cron: '0 8 * * 1', timezone: 'Asia/Shanghai' } : type === 'event' ? { type, event: 'FileUploaded' } : type === 'http' ? { type, path: '/webhook/start' } : { type: 'manual' } }) }
function updateTrigger(key: string, value: string) { emit('update-project', (draftProject) => { (draftProject.trigger as any)[key] = value }) }
function updateRuntime(key: string, value: unknown) { emit('update-project', (draftProject) => { (draftProject.runtime as any)[key] = value }) }
</script>

<style scoped>
.workflow-inspector { display:flex;min-height:0;flex-direction:column;overflow:hidden;background:var(--workflow-panel,#fff);color:var(--workflow-text,#334155); }.workflow-inspector__tabs { display:flex;min-height:44px;overflow:auto;border-bottom:1px solid var(--workflow-border,#e2e8f0); }.workflow-inspector__tabs button { display:inline-flex;min-width:58px;flex:1;align-items:center;justify-content:center;gap:5px;border-bottom:2px solid transparent;color:var(--workflow-muted,#64748b);font-size:10px;white-space:nowrap; }.workflow-inspector__tabs button:hover,.workflow-inspector__tabs button.active { border-bottom-color:var(--workflow-primary,#2563eb);color:var(--workflow-primary,#2563eb); }.workflow-inspector__body { min-height:0;overflow:auto;padding:15px; }.workflow-inspector__heading,.workflow-inspector__section-title { display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px; }.workflow-inspector__heading { justify-content:flex-start; }.workflow-inspector__heading h2,.workflow-inspector__section-title h2 { margin:0;color:var(--workflow-text,#1e293b);font-size:14px; }.workflow-inspector__heading p,.workflow-inspector__section-title p { margin:3px 0 0;color:var(--workflow-muted,#94a3b8);font-size:10px;line-height:1.45; }.workflow-inspector__node-icon { display:grid;width:34px;height:34px;place-items:center;border-radius:10px;background:color-mix(in srgb,var(--node-color) 14%,transparent);color:var(--node-color); }.workflow-field { position:relative;display:block;margin:0 0 12px;color:var(--workflow-muted,#64748b);font-size:10px;font-weight:700; }.workflow-field input,.workflow-field select,.workflow-field textarea,.workflow-variable-row input,.workflow-variable-row select { width:100%;min-height:35px;margin-top:5px;padding:0 9px;border:1px solid var(--workflow-border,#dbe4f0);border-radius:8px;background:var(--workflow-input,#fff);color:var(--workflow-text,#334155);font:12px inherit;outline:none; }.workflow-field textarea { min-heigh